static void RoundMedianCaps(){var sc=SceneManager.GetActiveScene();if(sc.path!="Assets/Scenes/Oasis/MobileOptimization/Gangstar City.unity")throw new Exception("Wrong scene");var all=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var root=all.Single(t=>t.name=="Median880 Rounded Railing");var curb=all.Single(t=>t.name=="green_base1 (24)").GetComponent<Renderer>().bounds;var source=all.Where(t=>t.name=="railing"&&t.GetComponent<MeshFilter>()).OrderBy(t=>Vector3.Distance(t.position,root.position)).First();var d=Read(source.GetComponent<MeshFilter>().sharedMesh);var src=F<Vector3[]>(d,"p").Select(source.TransformPoint).ToArray();var uv=F<Vector2[][]>(d,"uv")[0];var ids=F<int[]>(d,"ids");var sb=source.GetComponent<Renderer>().bounds;float radius=.70f,straight=curb.size.z-1.55f;var p=new List<Vector3>();var tex=new List<Vector2>();var idx=new List<int>();int modules=Mathf.CeilToInt(straight/1.75f);float segment=straight/modules;
foreach(int side in new[]{-1,1})for(int a=0;a<modules;a++){int offset=p.Count;foreach(var v in src){float along=(a+(v.z-sb.min.z)/sb.size.z)*segment-straight*.5f;p.Add(new Vector3(side*radius+side*(v.x-sb.center.x)*.65f,(v.y-sb.min.y)/sb.size.y*.90f,side*along));}tex.AddRange(uv);idx.AddRange(ids.Select(i=>i+offset));}
bool reverse=true;Vector2 sample=uv[0];Action<Vector3,Vector3,Vector3,Vector3> quad=(a,b,c,e)=>{int k=p.Count;p.AddRange(new[]{a,b,c,e});tex.AddRange(new[]{sample,sample,sample,sample});idx.AddRange(reverse?new[]{k,k+2,k+1,k,k+3,k+2}:new[]{k,k+1,k+2,k,k+2,k+3});};
foreach(int end in new[]{-1,1}){Func<float,float,float,Vector3> arc=(angle,offset,y)=>new Vector3(Mathf.Cos(angle)*(radius+offset),y,end*(straight*.5f+Mathf.Sin(angle)*(radius+offset)));reverse=end==1;foreach(float y in new[]{.13f,.79f})for(int s=0;s<20;s++){float a=s*Mathf.PI/20,b=(s+1)*Mathf.PI/20,w=.023f,h=.024f;var a0=arc(a,-w,y-h);var a1=arc(a,w,y-h);var a2=arc(a,w,y+h);var a3=arc(a,-w,y+h);var b0=arc(b,-w,y-h);var b1=arc(b,w,y-h);var b2=arc(b,w,y+h);var b3=arc(b,-w,y+h);quad(a0,b0,b1,a1);quad(a1,b1,b2,a2);quad(a2,b2,b3,a3);quad(a3,b3,b0,a0);}reverse=true;for(int j=1;j<4;j++){float angle=j*Mathf.PI/4;var c=arc(angle,0,0);float w=.029f;var corners=new[]{new Vector3(-w,0,-w),new Vector3(w,0,-w),new Vector3(w,0,w),new Vector3(-w,0,w)};for(int k=0;k<4;k++)quad(c+corners[k],c+corners[(k+1)%4],c+corners[(k+1)%4]+Vector3.up*.89f,c+corners[k]+Vector3.up*.89f);quad(c+corners[0]+Vector3.up*.89f,c+corners[1]+Vector3.up*.89f,c+corners[2]+Vector3.up*.89f,c+corners[3]+Vector3.up*.89f);}}
// Remove coincident triangles at the straight-module post joins.
var unique=new HashSet<string>();var clean=new List<int>();Func<Vector3,string> key=v=>Mathf.RoundToInt(v.x*10000)+","+Mathf.RoundToInt(v.y*10000)+","+Mathf.RoundToInt(v.z*10000);for(int i=0;i<idx.Count;i+=3){var keys=new[]{key(p[idx[i]]),key(p[idx[i+1]]),key(p[idx[i+2]])};Array.Sort(keys);if(unique.Add(string.Join("/",keys)))clean.AddRange(new[]{idx[i],idx[i+1],idx[i+2]});}var mesh=root.GetComponent<MeshFilter>().sharedMesh;mesh.Clear();mesh.SetVertices(p);mesh.SetUVs(0,tex);mesh.SetTriangles(clean,0);mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();mesh.UploadMeshData(false);EditorUtility.SetDirty(mesh);root.GetComponent<LODGroup>().RecalculateBounds();AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(sc);EditorSceneManager.SaveScene(sc);typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{sc,root.position+new Vector3(3,2.3f,straight*.5f+3.5f),root.position+new Vector3(0,.5f,straight*.5f-1.5f),"Median880-Rounded-End"});File.WriteAllText("FinalEnvironmentRoadReview/Median880Rounding.txt","SUCCESS smooth 20-segment half-circle rails at each end, three evenly spaced cap posts, no distorted cross panels around curves; straight X panels retained. Duplicate post triangles removed. Existing material/one renderer retained. Triangles="+clean.Count/3);}
